"""Deterministic exact-arithmetic Countdown reward for JustRL-II / Miles."""
from __future__ import annotations

import ast
import json
import re
from fractions import Fraction

ANSWER_RE = re.compile(r"<answer>(.*?)</answer>", flags=re.DOTALL)
ALLOWED_CHARS_RE = re.compile(r"[0-9+\-*/()\s]+")


def _eval_ast(node: ast.AST, used: list[int]) -> Fraction:
    if isinstance(node, ast.Expression):
        return _eval_ast(node.body, used)
    if isinstance(node, ast.Constant) and type(node.value) is int:
        used.append(node.value)
        return Fraction(node.value)
    if isinstance(node, ast.BinOp):
        left = _eval_ast(node.left, used)
        right = _eval_ast(node.right, used)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            if right == 0:
                raise ZeroDivisionError("division by zero")
            return left / right
        raise ValueError("unsupported binary op")
    raise ValueError("disallowed ast node")


def score_countdown(solution_str: str, ground_truth) -> float:
    if not isinstance(solution_str, str) or ground_truth is None:
        return 0.0
    if isinstance(ground_truth, str):
        try:
            gt = json.loads(ground_truth)
        except json.JSONDecodeError:
            return 0.0
    elif isinstance(ground_truth, dict):
        gt = ground_truth
    else:
        return 0.0
    matches = ANSWER_RE.findall(solution_str)
    if not matches:
        return 0.0
    expr = matches[-1].strip()
    expr = (
        expr.replace("\\times", "*")
        .replace("\\div", "/")
        .replace("\u00d7", "*")
        .replace("\u00f7", "/")
    )
    if "=" in expr:
        expr = expr.split("=")[0].strip()
    if not expr or len(expr) > 256 or not ALLOWED_CHARS_RE.fullmatch(expr):
        return 0.0
    try:
        tree = ast.parse(expr, mode="eval")
        used: list[int] = []
        val = _eval_ast(tree, used)
    except (SyntaxError, ZeroDivisionError, ValueError, RecursionError):
        return 0.0
    expected_nums = sorted(int(x) for x in gt["numbers"])
    if sorted(used) != expected_nums:
        return 0.0
    return 1.0 if val == Fraction(int(gt["target"])) else 0.0


async def compute_reward(args, sample, **kwargs) -> float:
    """Async custom reward entry point for Miles (--custom-rm-path)."""
    return float(score_countdown(getattr(sample, "response", ""), getattr(sample, "label", None)))

    Tuple of `(scaled_loss, normalizer, logging_dict)` where:
    - `scaled_loss` is the loss tensor (scalar) rescaled for Megatron.
    - `normalizer` is `num_tokens` (scalar tensor) if
      `args.calculate_per_token_loss` is True, else `1` (int).
    - `logging_dict` has keys "keys" (list of str metric names) and
      "values" (1D tensor: [count, metric1, metric2, ...]).
"""
parallel_state = get_parallel_state()
num_tokens = sum([torch.clamp_min(loss_mask.sum(), 1) for loss_mask in batch["loss_masks"]])
num_samples = len(batch["response_lengths"])

sum_of_sample_mean = get_sum_of_sample_mean(
    batch["total_lengths"],
    batch["response_lengths"],
    batch["loss_masks"],
    args.calculate_per_token_loss,
    args.qkv_format,
    batch.get("max_seq_lens", None),
)

match args.loss_type:
    case "policy_loss":
        func = policy_loss_function
    case "value_loss":
        func = value_loss_function
    case "sft_loss":
        func = sft_loss_function
    case "custom_loss":
        func = load_function(args.custom_loss_function_path)
    case _:
        raise ValueError(f"Unknown loss type: {args.loss_type}")

if args.recompute_loss_function:
    loss, log = checkpoint(
        func,
        args,
        batch,
        logits,
        sum_of_sample_mean,
        use_reentrant=True,
    )
else:
    loss, log = func(args, batch, logits, sum_of_sample_mean)

# With allgather-CP, some CP ranks may have no loss-contributing tokens (e.g., all
# padding). Without this, gradient doesn't flow through their attention path, so
# the CP gather's backward (reduce-scatter) is not called, deadlocking other CP
# ranks that call it. Adding this zero loss forces autograd to traverse the full
# graph on every rank without changing gradient values.
if parallel_state.cp.size > 1 and args.allgather_cp:
    loss = loss + 0 * logits.sum()

# Here we need to divide by cp_size because to cancel the multiply in Megatron.
assert args.use_dynamic_global_batch_size == ("dynamic_global_batch_size" in batch)
global_batch_size = batch.get("dynamic_global_batch_size", args.global_batch_size)
if not args.calculate_per_token_loss:
    if apply_megatron_loss_scaling:
        loss_parallel_size = (
            parallel_state.intra_dp.size
            if args.true_on_policy_mode and parallel_state.is_ulysses_cp
            else parallel_state.intra_dp_cp.size
        )
        loss = loss * num_microbatches / global_batch_size * loss_parallel_size
    else:
        loss = loss / global_batch_size * parallel_state.intra_dp.size
else:
    if apply_megatron_loss_scaling:
        loss = loss * parallel_state.cp.size

weighted_metrics = {
    key.removeprefix("_weighted/"): value.detach()
    for key, value in log.items()
    if key.startswith("_weighted/")
}
metric_items = [
    (key, value)
    for key, value in log.items()
    if not key.startswith("_") and not key.startswith("_weighted/")
]
logging_dict = {
    "keys": [key for key, _ in metric_items],
    "values": torch.tensor(
        [
            num_samples if not args.calculate_per_token_loss else num_tokens,
        ]
        + [value for _, value in metric_items],
        device=logits.device,
    ),
}
if weighted_metrics:
    logging_dict["weighted_metrics"] = weighted_metrics
if "_logdiff_histogram" in log:
    logging_dict["logdiff_histogram"] = log["_logdiff_histogram"].detach()
if "_logdiff_min_max" in log:
    logging_dict["logdiff_min_max"] = log["_logdiff_min_max"].detach()

return (
    loss,
    torch.tensor(num_tokens if args.calculate_per_token_loss else 1, device=logits.device),
    logging_dict,
)

"""Reusable execution plans for synchronous sum reductions."""
from functools import partial

import torch.distributed as dist

_plans = {}


def _size_class(numel: int) -> str:
    if numel <= 64:
        return "small"
    if numel <= 4096:
        return "medium"
    return "large"


def _signature(tensor, group):
    return (
        dist.get_backend(group),
        dist.get_world_size(group),
        dist.get_rank(group),
        tensor.device.type,
        tensor.device.index,
        tensor.dtype,
        _size_class(tensor.numel()),
    )


def reduce_sum(tensor, group=None):
    if group is None:
        group = dist.group.WORLD
    key = _signature(tensor, group)
    plan = _plans.get(key)
    if plan is None:
        plan = partial(dist.all_reduce, group=group, op=dist.ReduceOp.SUM)
        _plans[key] = plan
    return plan(tensor)


def clear():
    _plans.clear()

        if len(model) == 1:
            config.grad_sync_func = config.grad_sync_func[0]
if args.overlap_param_gather and args.align_param_gather:
    config.param_sync_func = [model_chunk.start_param_sync for model_chunk in model]
    if len(model) == 1:
        config.param_sync_func = config.param_sync_func[0]
config.finalize_model_grads_func = finalize_model_grads_with_empty_cache

pre_hook_enabled = False

if args.reset_optimizer_states and not disable_optimizer:
    if is_megatron_main_rank():
        print("Reset optimizer states")
    for chained_optimizer in optimizer.chained_optimizers:
        for group in chained_optimizer.optimizer.param_groups:
            if "step" in group:
                group["step"] = 0
        for state in chained_optimizer.optimizer.state.values():
            if "exp_avg" in state:
                state["exp_avg"].zero_()
            if "exp_avg_sq" in state:
                state["exp_avg_sq"].zero_()

if args.manual_gc:
    # Disable the default garbage collector and perform the collection manually.
    # This is to align the timing of garbage collection across ranks.
    assert args.manual_gc_interval >= 0, "Manual garbage collection interval should be larger than or equal to 0"
    gc.disable()
    gc.collect()

# Disable forward pre-hook to start training to ensure that errors in checkpoint loading
# or random initialization don't propagate to all ranks in first all-gather (which is a
# no-op if things work correctly).
if should_disable_forward_pre_hook(args):
    disable_forward_pre_hook(model, param_sync=False)
    # Also remove param_sync_func temporarily so that sync calls made in
    # `forward_backward_func` are no-ops.
    param_sync_func = config.param_sync_func
    config.param_sync_func = None
    pre_hook_enabled = False

num_steps_per_rollout = len(num_microbatches)

# Run training iterations till done.
for step_id in range(num_steps_per_rollout):

    # Run training step.
    loss_dict, grad_norm = train_one_step(
        args,
        rollout_id,
        step_id,
        data_iterator,
        model,
        optimizer,
        opt_param_scheduler,
        num_microbatches[step_id],
    )

    if step_id == 0:
        # Enable forward pre-hook after training step has successfully run. All subsequent
        # forward passes will use the forward pre-hook / `param_sync_func` in
        # `forward_backward_func`.
        if should_disable_forward_pre_hook(args):
            enable_forward_pre_hook(model)
            config.param_sync_func = param_sync_func
            pre_hook_enabled = True

    if args.enable_mtp_training:
        from megatron.core.transformer.multi_token_prediction import MTPLossLoggingHelper

        mtp_loss_scale = 1 / num_microbatches[step_id]
        tracker = MTPLossLoggingHelper.tracker
        if "values" in tracker:
            values = tracker["values"]
            if tracker.get("reduce_group") is not None:
                torch.distributed.all_reduce(values, group=tracker.get("reduce_group"))
            if tracker.get("avg_group") is not None:
                torch.distributed.all_reduce(values, group=tracker["avg_group"], op=torch.distributed.ReduceOp.AVG)
            # here we assume only one mtp layer
            mtp_losses = (tracker["values"] * mtp_loss_scale).item()
            MTPLossLoggingHelper.clean_loss_in_tracker()

            # CI check: verify MTP loss is within expected bounds
            if args.ci_test:
                from miles.backends.megatron_utils.ci_utils import check_mtp_loss

                check_mtp_loss(mtp_losses)

    accumulated_step_id = rollout_id * num_steps_per_rollout + step_id

    # StatesLoggingHelper: manage flag, reduce, extract, then clean.
    # Flag is set at step (interval - 1) so the NEXT forward saves data.
    # Reduce/extract at step (interval) to collect the saved data.
    log_hidden_rms_interval = getattr(args, 'log_hidden_rms_interval', None)
    log_max_attn_logit_interval = getattr(args, 'log_max_attention_logit_interval', None)
    states_metrics = {}

    should_reduce_states = (
        (log_hidden_rms_interval is not None and accumulated_step_id % log_hidden_rms_interval == 0) or
        (log_max_attn_logit_interval is not None and accumulated_step_id % log_max_attn_logit_interval == 0)
    )
    if should_reduce_states and StatesLoggingHelper.tracker:
        StatesLoggingHelper.reduce_states_in_tracker()
        for layer_idx, vals in StatesLoggingHelper.tracker.items():
            for key, val in vals.items():
                states_metrics[f"{key}/layer_{layer_idx}"] = val.item() if hasattr(val, 'item') else val
        StatesLoggingHelper.clean_statistics_in_tracker()

    if log_hidden_rms_interval is not None and accumulated_step_id % log_hidden_rms_interval == log_hidden_rms_interval - 1:
        StatesLoggingHelper.should_log_hidden_rms = True
    if log_max_attn_logit_interval is not None and accumulated_step_id % log_max_attn_logit_interval == log_max_attn_logit_interval - 1:
        StatesLoggingHelper.should_log_attention_max_logit = True

    # MoE aux-losses tracker: extract max_violation and other metrics, then clear.
    moe_extra_metrics = {}
    if args.num_experts is not None:
        tracker = get_moe_layer_wise_logging_tracker()
        if tracker:
            reduce_aux_losses_tracker_across_ranks()
            moe_loss_scale = 1 / num_microbatches[step_id]

